#include <bits/stdc++.h>
using namespace std;

using i64 = int64_t;
using pii = pair<int, int>;

template<typename T, typename U> inline T chmin(T& a, const U& b) { return a > b ? a = b, a : a; }
template<typename T, typename U> inline T chmax(T& a, const U& b) { return a < b ? a = b, a : a; }

#define loop(i, a, b) for (int i = (a), _b = (b); i < _b; ++i)
#define rep(i, n) loop(i, 0, n)

constexpr int MAX_N = 205;
constexpr int MAX_M = MAX_N * MAX_N;
#define prev some

int readInt() { int x; cin >> x; return x; }

int prev_edge[MAX_M], visited_node[MAX_N], adj_head[MAX_N], edge_src[MAX_M], edge_cap[MAX_M], edge_dst[MAX_M], edge_idx = 0;
int input_grid[MAX_N][MAX_N], output_grid[MAX_N][MAX_N], red_mark[MAX_N][MAX_N], block_mark[MAX_N][MAX_N];
int dist_map[MAX_N][MAX_N], counter_var, red_dist[MAX_N], bfs_seen[MAX_N];
pii bfs_q[MAX_N];
const int dx[4] = {0, -1, 0, 1};
const int dy[4] = {1, 0, -1, 0};

void linkEdge(int u, int v, int uv_cap, int vu_cap) {
	edge_src[edge_idx] = u;
	edge_dst[edge_idx] = v;
	edge_cap[edge_idx] = uv_cap;
	prev_edge[edge_idx] = adj_head[u];
	adj_head[u] = edge_idx++;
	edge_src[edge_idx] = v;
	edge_dst[edge_idx] = u;
	edge_cap[edge_idx] = vu_cap;
	prev_edge[edge_idx] = adj_head[v];
	adj_head[v] = edge_idx++;
}

int dfsFlow(int node, int target, int flow = 2000000000) {
	if (node == target) return flow;
	if (visited_node[node]++) return 0;
	for (int e = adj_head[node]; ~e; e = prev_edge[e]) if (edge_cap[e]) {
		int next_node = edge_dst[e];
		int flow_pushed = dfsFlow(next_node, target, min(flow, edge_cap[e]));
		if (flow_pushed) {
			edge_cap[e] -= flow_pushed;
			edge_cap[e ^ 1] += flow_pushed;
			return flow_pushed;
		}
	}
	return 0;
}

int maxFlow(int src, int dst) {
	int total = 0;
	for (;;) {
		memset(visited_node, 0, sizeof visited_node);
		int delta = dfsFlow(src, dst);
		total += delta;
		if (!delta) break;
	}
	return total;
}

int main() {
	ios::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
	int n = readInt(), dt = readInt();
	memset(adj_head, -1, sizeof adj_head);
	memset(dist_map, 63, sizeof dist_map);
	rep(i, MAX_N) dist_map[i][i] = 0;
	rep(x, n) rep(y, n) {
		char c; cin >> c;
		if (c == 'Y') block_mark[x][y] = 1;
		else if (c == 'Z') red_mark[x][y] = 1;
		else input_grid[x][y] = c - '0';
	}
	rep(x, n) rep(y, n) {
		char c; cin >> c;
		if (c != 'Y' && c != 'Z') {
			output_grid[x][y] = c - '0';
			rep(d, 4) {
				int nx = x + dx[d], ny = y + dy[d];
				if (nx >= 0 && ny >= 0 && nx < n && ny < n && !block_mark[nx][ny] && !red_mark[nx][ny])
					dist_map[x * n + y][nx * n + ny] = 1;
			}
		}
	}
	int node_count = n * n;
	rep(k, node_count) rep(i, node_count) rep(j, node_count)
		if (dist_map[i][k] + dist_map[k][j] < dist_map[i][j])
			dist_map[i][j] = dist_map[i][k] + dist_map[k][j];
	int qf = 0, qr = 0;
	memset(red_dist, 63, sizeof red_dist);
	rep(i, n) rep(j, n)
		if (red_mark[i][j]) {
			bfs_q[qr++] = {i, j};
			red_dist[i * n + j] = 0;
		}
	while (qf != qr) {
		auto cur = bfs_q[qf++];
		int x = cur.first, y = cur.second;
		rep(d, 4) {
			int nx = x + dx[d], ny = y + dy[d];
			if (nx >= 0 && ny >= 0 && nx < n && ny < n && !block_mark[nx][ny] && !red_mark[nx][ny] && red_dist[nx * n + ny] > 1e9) {
				red_dist[nx * n + ny] = red_dist[x * n + y] + 1;
				bfs_q[qr++] = {nx, ny};
			}
		}
	}
	int sink_node = MAX_N - 1, source_node = MAX_N - 2;
	rep(start_node, node_count) {
		memset(bfs_seen, 0, sizeof bfs_seen);
		qf = 0; qr = 0;
		int sx = start_node / n, sy = start_node % n;
		if (block_mark[sx][sy] || red_mark[sx][sy]) continue;
		bfs_q[qr++] = {sx, sy};
		bfs_seen[start_node] = 1;
		while (qf != qr) {
			int x = bfs_q[qf].first, y = bfs_q[qf++].second;
			if (dist_map[start_node][x * n + y] <= dt)
				linkEdge(start_node << 1, (x * n + y) << 1 | 1, 1000, 0);
			if (dist_map[start_node][x * n + y] == red_dist[x * n + y]) continue;
			rep(d, 4) {
				int nx = x + dx[d], ny = y + dy[d], nid = nx * n + ny;
				if (nx >= 0 && ny >= 0 && nx < n && ny < n && !block_mark[nx][ny] && !red_mark[nx][ny] && dist_map[start_node][nid] <= red_dist[nid] && dist_map[start_node][nid] <= dt && dist_map[start_node][nid] > dist_map[start_node][x * n + y] && !bfs_seen[nid]) {
					bfs_q[qr++] = {nx, ny};
					bfs_seen[nid] = 1;
				}
			}
		}
	}
	rep(i, node_count) linkEdge(source_node, i << 1, input_grid[i / n][i % n], 0);
	rep(i, node_count) linkEdge((i << 1) | 1, sink_node, output_grid[i / n][i % n], 0);
	cout << maxFlow(source_node, sink_node);
}
